        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String input;
        int ans = 0;
        boolean met = false;

        while ((input = br.readLine()) != null) {
            java.util.regex.Matcher matcher = java.util.regex.Pattern.compile("B").matcher(input);
